import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"46、【升】 巽下坤上","description":"横渠易说 - 46、【升】 巽下坤上","frontmatter":{"title":"46、【升】 巽下坤上","description":"横渠易说 - 46、【升】 巽下坤上"},"headers":[],"relativePath":"zh/classics/hengqu/048.md","filePath":"zh/classics/hengqu/048.md"}'),l={name:"zh/classics/hengqu/048.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_46、【升】-巽下坤上" tabindex="-1">46、【升】 巽下坤上 <a class="header-anchor" href="#_46、【升】-巽下坤上" aria-label="Permalink to “46、【升】 巽下坤上”">​</a></h1><h3 id="彖曰-柔以时升-巽而顺-刚中而应-是以大亨。-用见大人勿恤-有庆也-南征吉-志行也。" tabindex="-1">彖曰：柔以时升，巽而顺，刚中而应，是以大亨。“用见大人勿恤”，有庆也，“南征吉”，志行也。 <a class="header-anchor" href="#彖曰-柔以时升-巽而顺-刚中而应-是以大亨。-用见大人勿恤-有庆也-南征吉-志行也。" aria-label="Permalink to “彖曰：柔以时升，巽而顺，刚中而应，是以大亨。“用见大人勿恤”，有庆也，“南征吉”，志行也。”">​</a></h3><h3 id="象曰-地中生木-升-君子以顺德积小以高大。" tabindex="-1">象曰：地中生木，升，君子以顺德积小以高大。 <a class="header-anchor" href="#象曰-地中生木-升-君子以顺德积小以高大。" aria-label="Permalink to “象曰：地中生木，升，君子以顺德积小以高大。”">​</a></h3><p>萃者聚也，聚而上者谓之升，故受之以升。 乾之九二利见大人而以时之止，升之九二有六五配合之庆，故可见大人之德，南征而勿恤也。</p><h3 id="初六-允升-大吉。-象曰-允升大吉-上合志也。" tabindex="-1">初六，允升，大吉。 象曰：“允升大吉”，上合志也。 <a class="header-anchor" href="#初六-允升-大吉。-象曰-允升大吉-上合志也。" aria-label="Permalink to “初六，允升，大吉。 象曰：“允升大吉”，上合志也。”">​</a></h3><p>允，信也。自信于己，与上合志而升。</p><h3 id="九二-孚乃利用禴-无咎。-象曰-九二之孚-有喜也。" tabindex="-1">九二，孚乃利用禴，无咎。 象曰：九二之孚，有喜也。 <a class="header-anchor" href="#九二-孚乃利用禴-无咎。-象曰-九二之孚-有喜也。" aria-label="Permalink to “九二，孚乃利用禴，无咎。 象曰：九二之孚，有喜也。”">​</a></h3><p>与萃六二同。</p><h3 id="九三-升虚邑。-象曰-升虚邑-无所疑也。" tabindex="-1">九三，升虚邑。 象曰：“升虚邑”，无所疑也。 <a class="header-anchor" href="#九三-升虚邑。-象曰-升虚邑-无所疑也。" aria-label="Permalink to “九三，升虚邑。 象曰：“升虚邑”，无所疑也。”">​</a></h3><p>上皆阴柔，往无所疑。</p><h3 id="六四-王用亨于岐山-吉无咎。-象曰-王用亨于岐山-顺事也。" tabindex="-1">六四，王用亨于岐山，吉无咎。 象曰：“王用亨于岐山”，顺事也。 <a class="header-anchor" href="#六四-王用亨于岐山-吉无咎。-象曰-王用亨于岐山-顺事也。" aria-label="Permalink to “六四，王用亨于岐山，吉无咎。 象曰：“王用亨于岐山”，顺事也。”">​</a></h3><h3 id="六五-贞吉升阶。-象曰-贞吉升阶-大得志也。" tabindex="-1">六五，贞吉升阶。 象曰：“贞吉升阶”，大得志也。 <a class="header-anchor" href="#六五-贞吉升阶。-象曰-贞吉升阶-大得志也。" aria-label="Permalink to “六五，贞吉升阶。 象曰：“贞吉升阶”，大得志也。”">​</a></h3><p>柔中极尊，不拒来者，使物皆阶己而升，正而且吉，志宜大获也。易所谓“得志”者，圣贤获其愿欲。得臣无家，尧之志也，贞吉升阶，舜之志也。</p><h3 id="上六-冥升-利于不息之贞。-象曰-冥升在上-消不富也。" tabindex="-1">上六，冥升，利于不息之贞。 象曰：冥升在上，消不富也。 <a class="header-anchor" href="#上六-冥升-利于不息之贞。-象曰-冥升在上-消不富也。" aria-label="Permalink to “上六，冥升，利于不息之贞。 象曰：冥升在上，消不富也。”">​</a></h3>',14)])])}const b=e(l,[["render",t]]);export{p as __pageData,b as default};
